import { canonicalJson } from "./constants.js";
import {
  emitApplicationSource,
  emitDeterministicFile,
  sourceMemberAccess,
  type ApplicationReadmeMetadata,
  type EmittedSourceFile,
  type ResolvedField,
  type ResolvedOperation,
  type ResolvedWorkload,
  type SourceProvenance,
} from "./source-emitter.js";

const generatedHeader =
  "// @generated by cloudmarkup.event-application-generator@1.0.0; do not edit.\n";
const extensionHeader =
  "// @user-owned CloudMarkup extension point; regeneration never overwrites this file.\n";

function compareUtf16(left: string, right: string): number {
  if (left === right) return 0;
  return left < right ? -1 : 1;
}

type EventResolvedOperation = ResolvedOperation & {
  readonly event: NonNullable<ResolvedOperation["event"]>;
};

function operationFor(workload: ResolvedWorkload): EventResolvedOperation {
  const operation = workload.operations[0];
  if (
    operation === undefined ||
    workload.operations.length !== 1 ||
    operation.event === undefined
  ) {
    throw new Error(
      `Event workload ${workload.workloadId} must contain one resolved event operation.`,
    );
  }
  return { ...operation, event: operation.event };
}

function provenance(workload: ResolvedWorkload): SourceProvenance {
  const operation = operationFor(workload);
  const event = operation.event;
  return {
    workloadIds: [workload.workloadId],
    operationIds: [operation.id],
    contractIds: [
      operation.behaviorContractId,
      operation.entity.contractId,
      event.eventContractId,
      ...workload.tests.map((test) => test.testCaseContractId),
    ].sort(compareUtf16),
    edgeIds: [...new Set([operation.triggerEdgeId, operation.dataEdgeId])].sort(
      compareUtf16,
    ),
    environmentBindingIds: workload.environment
      .map((binding) => binding.bindingId)
      .sort(compareUtf16),
    resourceTargetKeys: workload.environment
      .flatMap((binding) =>
        binding.targetKey === undefined ? [] : [binding.targetKey],
      )
      .sort(compareUtf16),
    extensionPointIds: [...workload.extensionPointIds].sort(compareUtf16),
  };
}

function typeFor(field: ResolvedField): string {
  const scalar = (() => {
    switch (field.scalarType) {
      case "integer":
      case "number":
        return "number";
      case "boolean":
        return "boolean";
      case "integer-list":
      case "number-list":
        return "readonly number[]";
      case "boolean-list":
        return "readonly boolean[]";
      case "string-list":
        return "readonly string[]";
      default:
        return "string";
    }
  })();
  return field.nullable ? `${scalar} | null` : scalar;
}

function renderTypes(operation: ResolvedOperation): string {
  const fields = operation.entity.fields
    .map(
      (field) =>
        `  readonly ${JSON.stringify(field.name)}${field.required ? "" : "?"}: ${typeFor(field)};`,
    )
    .join("\n");
  return `${generatedHeader}export interface EventPayload {
${fields}
}

export interface FieldDescriptor {
  readonly name: string;
  readonly required: boolean;
  readonly nullable: boolean;
  readonly scalarType: string;
}

export const payloadFields: readonly FieldDescriptor[] = ${JSON.stringify(operation.entity.fields)};

function valueMatches(value: unknown, scalarType: string): boolean {
  if (scalarType === "integer") return typeof value === "number" && Number.isInteger(value);
  if (scalarType === "number") return typeof value === "number" && Number.isFinite(value);
  if (scalarType === "boolean") return typeof value === "boolean";
  if (scalarType.endsWith("-list")) {
    if (!Array.isArray(value)) return false;
    const itemType = scalarType.slice(0, -5);
    return value.every((item) => valueMatches(item, itemType));
  }
  return typeof value === "string";
}

export function validatePayload(value: unknown): EventPayload {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new Error("Event payload must be an object.");
  }
  const record = value as Record<string, unknown>;
  for (const field of payloadFields) {
    const member = record[field.name];
    if (member === undefined) {
      if (field.required) throw new Error(\`Missing required field: \${field.name}\`);
      continue;
    }
    if (member === null) {
      if (!field.nullable) throw new Error(\`Field cannot be null: \${field.name}\`);
      continue;
    }
    if (!valueMatches(member, field.scalarType)) {
      throw new Error(\`Invalid field type: \${field.name}\`);
    }
  }
  return record as unknown as EventPayload;
}

export interface S3Event {
  readonly Records: readonly {
    readonly eventName: string;
    readonly eventTime: string;
    readonly s3: {
      readonly bucket: { readonly name: string };
      readonly object: {
        readonly key: string;
        readonly eTag: string;
        readonly size: number;
        readonly versionId: string;
        readonly sequencer: string;
      };
    };
  }[];
}

export interface SqsEvent {
  readonly Records: readonly {
    readonly messageId: string;
    readonly body: string;
    readonly attributes?: Readonly<Record<string, string>>;
  }[];
}

export interface SnsEvent {
  readonly Records: readonly {
    readonly Sns: {
      readonly MessageId: string;
      readonly Message: string;
      readonly Timestamp?: string;
    };
  }[];
}

export interface EventBridgeEvent {
  readonly id: string;
  readonly source: string;
  readonly "detail-type": string;
  readonly time: string;
  readonly detail: unknown;
}

export interface BatchItemFailure {
  readonly itemIdentifier: string;
}

export interface SqsBatchResponse {
  readonly batchItemFailures: readonly BatchItemFailure[];
}
`;
}

function renderBindings(workload: ResolvedWorkload): string {
  const getters = workload.environment
    .map(
      (binding) =>
        `export function get_${binding.name}(): string { return requiredEnvironment(${JSON.stringify(binding.name)}); }`,
    )
    .join("\n");
  return `${generatedHeader}function requiredEnvironment(name: string): string {
  const value = process.env[name];
  if (value === undefined || value.length === 0) {
    throw new Error(\`Missing required environment binding: \${name}\`);
  }
  return value;
}

${getters}
`;
}

function renderIdempotency(): string {
  return `${generatedHeader}export interface IdempotencyHook {
  execute(
    identity: string,
    operation: () => Promise<void>,
  ): Promise<"processed" | "duplicate">;
}

/**
 * The generated handler always deduplicates identities within one invocation.
 * A preserved user extension may provide durable cross-invocation claims.
 * Generated code never invents a store or infers an identity from payload prose.
 */
export function invocationDeduplicator(): (identity: string) => boolean {
  const claimed = new Set<string>();
  return (identity) => {
    if (claimed.has(identity)) return false;
    claimed.add(identity);
    return true;
  };
}

export async function runIdempotent(
  identity: string,
  firstClaim: (identity: string) => boolean,
  durableHook: IdempotencyHook | undefined,
  operation: () => Promise<void>,
): Promise<"processed" | "duplicate"> {
  if (!firstClaim(identity)) return "duplicate";
  if (durableHook !== undefined) {
    return await durableHook.execute(identity, operation);
  }
  await operation();
  return "processed";
}
`;
}

function deliveryLiteral(operation: ResolvedOperation): string {
  const event = operation.event;
  if (event === undefined) throw new Error("Missing event metadata.");
  return JSON.stringify({
    contractId: event.eventContractId,
    pattern: event.pattern,
    transportKind: event.transportKind,
    ordering: event.delivery.ordering,
    duplicates: event.delivery.duplicates,
    delivery: event.delivery.delivery,
    batchSize: event.batchSize,
    partialBatchFailure: event.partialBatchFailure,
    timeoutMilliseconds: event.timeoutMilliseconds,
    maximumAttempts: event.maximumAttempts,
    ...(event.deadLetterTargetKey === undefined
      ? {}
      : { deadLetterTargetKey: event.deadLetterTargetKey }),
    ...(event.filterPrefix === undefined
      ? {}
      : { filterPrefix: event.filterPrefix }),
    ...(event.filterSuffix === undefined
      ? {}
      : { filterSuffix: event.filterSuffix }),
    ...(event.scheduleExpression === undefined
      ? {}
      : { scheduleExpression: event.scheduleExpression }),
    idempotency: event.idempotency,
  });
}

function renderLogging(): string {
  return `import { createHash } from "node:crypto";

function opaqueIdentifier(value: string): string {
  return createHash("sha256").update(value).digest("hex").slice(0, 32);
}

function boundedDetail(value: unknown): string | number | boolean {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value === "boolean") return value;
  if (
    typeof value === "string" &&
    value.length <= 96 &&
    /^[A-Za-z0-9._:-]+$/.test(value)
  ) {
    return value;
  }
  return typeof value === "string" ? opaqueIdentifier(value) : "redacted";
}

function log(
  level: "info" | "error",
  event: string,
  correlationSeed: string,
  details: Readonly<Record<string, unknown>> = {},
): void {
  const boundedDetails = Object.fromEntries(
    Object.entries(details).map(([key, value]) => [
      key.slice(0, 64),
      boundedDetail(value),
    ]),
  );
  console.log(JSON.stringify({
    level,
    event,
    correlationId: opaqueIdentifier(correlationSeed),
    ...boundedDetails,
  }));
}
`;
}

function renderS3Handler(operation: ResolvedOperation): string {
  return `import { DynamoDBClient, PutItemCommand } from "@aws-sdk/client-dynamodb";
import { durableIdempotencyHook, processEvent } from "./generated/runtime-extension.js";
import { get_${operation.tableEnvironmentName} } from "./generated/bindings.js";
import { invocationDeduplicator, runIdempotent } from "./generated/idempotency.js";
import { validatePayload, type EventPayload, type S3Event } from "./generated/types.js";

export const deliveryPolicy = ${deliveryLiteral(operation)} as const;

export type MetadataWriter = (payload: EventPayload) => Promise<void>;
let writeMetadata: MetadataWriter = async (payload) => {
  const item = Object.fromEntries(
    Object.entries(payload).map(([name, value]) => [
      name,
      typeof value === "number" ? { N: String(value) } : { S: String(value) },
    ]),
  );
  await new DynamoDBClient({}).send(
    new PutItemCommand({ TableName: get_${operation.tableEnvironmentName}(), Item: item }),
  );
};

export function setMetadataWriterForTest(writer: MetadataWriter): void {
  writeMetadata = writer;
}

function requiredS3String(value: unknown, sourcePath: string): string {
  if (typeof value !== "string" || value.length === 0) {
    throw new Error(\`Invalid required S3 metadata at \${sourcePath}: expected a non-empty string.\`);
  }
  return value;
}

function requiredS3Size(value: unknown, sourcePath: string): number {
  if (typeof value !== "number" || !Number.isSafeInteger(value) || value < 0) {
    throw new Error(\`Invalid required S3 metadata at \${sourcePath}: expected a non-negative safe integer.\`);
  }
  return value;
}

function decodeS3ObjectKey(value: unknown, sourcePath: string): string {
  const encodedKey = requiredS3String(value, sourcePath);
  try {
    return decodeURIComponent(encodedKey.replace(/\\+/g, " "));
  } catch {
    throw new Error(\`Invalid required S3 metadata at \${sourcePath}: expected a valid URL-encoded string.\`);
  }
}

${renderLogging()}
export async function handler(event: S3Event): Promise<void> {
  const firstClaim = invocationDeduplicator();
  for (const [recordIndex, record] of event.Records.entries()) {
    const object = record.s3.object;
    const sourcePath = "$.Records[" + String(recordIndex) + "].s3.object";
    const bucket = requiredS3String(
      record.s3.bucket.name,
      "$.Records[" + String(recordIndex) + "].s3.bucket.name",
    );
    const key = decodeS3ObjectKey(object.key, sourcePath + ".key");
    const eTag = requiredS3String(object.eTag, sourcePath + ".eTag");
    const size = requiredS3Size(object.size, sourcePath + ".size");
    const versionId = requiredS3String(object.versionId, sourcePath + ".versionId");
    const sequencer = requiredS3String(object.sequencer, sourcePath + ".sequencer");
    const identity = [bucket, key, versionId, eTag, sequencer].join(":");
    const payload = validatePayload({
      bucket,
      key,
      eTag,
      size,
      versionId,
      sequencer,
    });
    const outcome = await runIdempotent(
      identity,
      firstClaim,
      durableIdempotencyHook,
      async () => {
        await writeMetadata(payload);
        await processEvent(payload, { identity, operationId: ${JSON.stringify(operation.id)} });
      },
    );
    if (outcome === "duplicate") {
      log("info", "duplicate-skipped", identity);
      continue;
    }
    log("info", "s3-object-metadata-recorded", identity, { operationId: ${JSON.stringify(operation.id)} });
  }
}
`;
}

function renderSqsHandler(operation: ResolvedOperation): string {
  return `import { durableIdempotencyHook, processEvent } from "./generated/runtime-extension.js";
import { invocationDeduplicator, runIdempotent } from "./generated/idempotency.js";
import { validatePayload, type SqsBatchResponse, type SqsEvent } from "./generated/types.js";

export const deliveryPolicy = ${deliveryLiteral(operation)} as const;
${renderLogging()}
export async function handler(event: SqsEvent): Promise<SqsBatchResponse> {
  const failures: { itemIdentifier: string }[] = [];
  const firstClaim = invocationDeduplicator();
  for (const record of event.Records) {
    try {
      const payload = validatePayload(JSON.parse(record.body));
      const outcome = await runIdempotent(
        record.messageId,
        firstClaim,
        durableIdempotencyHook,
        async () => {
          await processEvent(payload, {
            identity: record.messageId,
            operationId: ${JSON.stringify(operation.id)},
          });
        },
      );
      if (outcome === "duplicate") {
        log("info", "duplicate-skipped", record.messageId);
        continue;
      }
      log("info", "message-processed", record.messageId, {
        operationId: ${JSON.stringify(operation.id)},
        payloadFieldCount: Object.keys(payload).length,
      });
    } catch (error) {
      failures.push({ itemIdentifier: record.messageId });
      log("error", "message-failed", record.messageId, {
        errorCode: error instanceof SyntaxError ? "invalid-json" : "payload-contract-invalid",
      });
    }
  }
  return { batchItemFailures: failures };
}
`;
}

function renderSnsHandler(operation: ResolvedOperation): string {
  return `import { durableIdempotencyHook, processEvent } from "./generated/runtime-extension.js";
import { invocationDeduplicator, runIdempotent } from "./generated/idempotency.js";
import { validatePayload, type SnsEvent } from "./generated/types.js";

export const deliveryPolicy = ${deliveryLiteral(operation)} as const;
${renderLogging()}
export async function handler(event: SnsEvent): Promise<void> {
  const firstClaim = invocationDeduplicator();
  for (const record of event.Records) {
    const identity = record.Sns.MessageId;
    const payload = validatePayload(JSON.parse(record.Sns.Message));
    const outcome = await runIdempotent(
      identity,
      firstClaim,
      durableIdempotencyHook,
      async () => {
        await processEvent(payload, {
          identity,
          operationId: ${JSON.stringify(operation.id)},
        });
      },
    );
    if (outcome === "duplicate") {
      log("info", "duplicate-skipped", identity);
      continue;
    }
    log("info", "notification-processed", identity, {
      operationId: ${JSON.stringify(operation.id)},
      payloadFieldCount: Object.keys(payload).length,
    });
  }
}
`;
}

function renderEventBridgeHandler(
  operation: ResolvedOperation,
  scheduled: boolean,
): string {
  return `import { durableIdempotencyHook, processEvent } from "./generated/runtime-extension.js";
import { invocationDeduplicator, runIdempotent } from "./generated/idempotency.js";
import { validatePayload, type EventBridgeEvent } from "./generated/types.js";

export const deliveryPolicy = ${deliveryLiteral(operation)} as const;
${renderLogging()}
export async function handler(event: EventBridgeEvent): Promise<void> {
  const payload = validatePayload(${scheduled ? "{ eventId: event.id }" : "event.detail"});
  const firstClaim = invocationDeduplicator();
  const outcome = await runIdempotent(
    event.id,
    firstClaim,
    durableIdempotencyHook,
    async () => {
      await processEvent(payload, {
        identity: event.id,
        operationId: ${JSON.stringify(operation.id)},
      });
    },
  );
  if (outcome === "duplicate") {
    log("info", "duplicate-skipped", event.id);
    return;
  }
  log("info", ${JSON.stringify(scheduled ? "schedule-fired" : "event-target-processed")}, event.id, {
    operationId: ${JSON.stringify(operation.id)},
    sourceIdentifier: opaqueIdentifier(event.source),
    detailTypeIdentifier: opaqueIdentifier(event["detail-type"]),
    payloadFieldCount: Object.keys(payload).length,
  });
}
`;
}

function renderStepFunctionsHandler(operation: ResolvedOperation): string {
  const partition = operation.entity.fields.find(
    (field) => field.name === operation.entity.partitionKey,
  );
  const access = sourceMemberAccess("payload", operation.entity.partitionKey);
  const identity =
    partition?.required === true &&
    !partition.nullable &&
    ["string", "uuid", "date", "timestamp", "binary-reference"].includes(
      partition.scalarType,
    )
      ? access
      : `String(${access})`;
  return `import { durableIdempotencyHook, processEvent } from "./generated/runtime-extension.js";
import { invocationDeduplicator, runIdempotent } from "./generated/idempotency.js";
import { validatePayload, type EventPayload } from "./generated/types.js";

export const deliveryPolicy = ${deliveryLiteral(operation)} as const;
${renderLogging()}
export async function handler(input: unknown): Promise<EventPayload> {
  const payload = validatePayload(input);
  const identity = ${identity};
  const correlationId =
    typeof payload.correlationId === "string"
      ? payload.correlationId
      : identity;
  const firstClaim = invocationDeduplicator();
  const outcome = await runIdempotent(
    identity,
    firstClaim,
    durableIdempotencyHook,
    async () => {
      await processEvent(payload, {
        identity,
        operationId: ${JSON.stringify(operation.id)},
      });
    },
  );
  if (outcome === "duplicate") {
    log("info", "duplicate-skipped", correlationId);
    return payload;
  }
  log("info", "workflow-task-processed", correlationId, {
    operationId: ${JSON.stringify(operation.id)},
  });
  return payload;
}
`;
}

function renderHandler(operation: ResolvedOperation): string {
  const event = operation.event;
  if (event === undefined) throw new Error("Missing event metadata.");
  const body = (() => {
    switch (event.pattern) {
      case "s3-image-metadata":
        return renderS3Handler(operation);
      case "sqs-consumer-dlq":
        return renderSqsHandler(operation);
      case "sns-fanout-consumer":
        return renderSnsHandler(operation);
      case "eventbridge-scheduled":
        return renderEventBridgeHandler(operation, true);
      case "eventbridge-target":
        return renderEventBridgeHandler(operation, false);
      case "step-functions-task":
        return renderStepFunctionsHandler(operation);
    }
  })();
  return `${generatedHeader}${body}`;
}

function payloadFixture(operation: ResolvedOperation): Record<string, unknown> {
  return Object.fromEntries(
    operation.entity.fields.map((field) => {
      const value = (() => {
        switch (field.name) {
          case "bucket":
            return "fixture-image-input";
          case "key":
            return "incoming/example.jpg";
          case "eTag":
            return "fixture-etag";
          case "size":
            return 42;
          case "versionId":
            return "fixture-version";
          case "sequencer":
            return "0001";
          case "correlationId":
            return "correlation-fixture-1";
          default:
            if (field.scalarType === "integer" || field.scalarType === "number")
              return 1;
            if (field.scalarType === "boolean") return true;
            if (field.scalarType.endsWith("-list")) return [];
            return `fixture-${field.name}`;
        }
      })();
      return [field.name, value];
    }),
  );
}

